/**
 * Image optimization utilities.
 *
 * Converts image paths from legacy formats (.png, .jpg, .jpeg) to
 * optimized WebP format. Original files are preserved on disk — this
 * only rewrites the URL the browser requests.
 */

import { buildApiUrl } from './api';

const CONVERTIBLE_RE = /\.(png|jpe?g)$/i;

/**
 * Rewrite an image path so the browser fetches the WebP version
 * that was generated by `scripts/optimize-images.mjs`.
 *
 * - `/logos/altunsa-logo.png`  → `/logos/altunsa-logo.webp`
 * - `/aylux/product.jpg`      → `/aylux/product.webp`
 * - `/already-fine.webp`      → `/already-fine.webp` (no-op)
 * - External URLs (http/data) → returned unchanged
 */
export function toWebp(src: string | undefined | null): string {
  if (!src) return '';
  // Don't touch external URLs or data URIs
  if (src.startsWith('http') || src.startsWith('data:')) return src;
  return src.replace(CONVERTIBLE_RE, '.webp');
}

/**
 * Resolve an image URL for rendering INSIDE the admin SPA.
 *
 * Two transformations are needed that the public site's <ImageWithFallback>
 * handles via `toWebp() + fallbackSrc`. Admin uses bare <img> in many
 * places, so we centralise the logic here:
 *
 *   1. `/api/uploads/<file>` — uploaded via the admin panel and stored on
 *      the API server's volume. The admin SPA lives on the frontend host
 *      (karahoca.com) but the file is at api.karahoca.com. Prepend the
 *      configured `VITE_BACKEND_URL` so the cross-subdomain request lands
 *      on the right origin.
 *
 *   2. `/<static>/file.png` — static assets shipped with the SPA. The
 *      build pipeline (`scripts/prune-dist.mjs`) drops the PNG copy when a
 *      WebP sibling exists, so admin requests for `.png` come back 404 on
 *      production. Rewrite to `.webp` so we hit the surviving file.
 *
 *   3. Already-absolute http(s)/data URIs are returned unchanged.
 *
 * Uploaded files (`/api/uploads/*`) keep their original extension because
 * the server stores them as-is (no WebP transcoding pipeline). Don't run
 * toWebp on them or we'd point at a non-existent `.webp`.
 */
export function resolveAdminImage(src: string | undefined | null): string {
  if (!src) return '';
  if (src.startsWith('http') || src.startsWith('data:')) return src;
  if (src.startsWith('/api/uploads/')) return buildApiUrl(src);
  return toWebp(src);
}

// ─── Admin uploads: resized variants ─────────────────────────────────────
// Product photos uploaded through the admin are stored as-is (2–8 MB PNGs of
// ~2800 px) and were downloaded at full size for ~250 px cards — ~23 MB on
// the AYLUX page. The API serves resized WebP copies at these widths
// (`/api/uploads/<file>?w=640`, server/services/uploadVariants.mjs); keep the
// list in sync with UPLOAD_VARIANT_WIDTHS there.
const UPLOAD_VARIANT_WIDTHS = [160, 320, 480, 640, 960, 1280] as const;
const RESIZABLE_UPLOAD_RE = /\/api\/uploads\/[^/?#]+\.(png|jpe?g|webp)$/i;

export const isResizableUpload = (src: string | undefined | null): src is string =>
  !!src && RESIZABLE_UPLOAD_RE.test(src);

const nearestVariantWidth = (width: number) =>
  UPLOAD_VARIANT_WIDTHS.find((w) => w >= width) ?? UPLOAD_VARIANT_WIDTHS[UPLOAD_VARIANT_WIDTHS.length - 1];

/**
 * Props for <ImageWithFallback> showing `src` at roughly `displayWidth` CSS
 * px (the `sizes` hint). Uploads get a srcset of resized WebP variants — 1×
 * and 2× the display width — with the untouched original as the fallback
 * if a variant fails; static assets keep the existing `.webp` rewrite.
 */
export const responsiveImageProps = (
  src: string | undefined | null,
  displayWidth: number,
  sizes = `${displayWidth}px`,
) => {
  const original = src ?? '';
  if (!isResizableUpload(original)) {
    return { src: toWebp(original), fallbackSrc: original };
  }
  const widths = [...new Set([nearestVariantWidth(displayWidth), nearestVariantWidth(displayWidth * 2)])];
  return {
    src: `${original}?w=${widths[widths.length - 1]}`,
    fallbackSrc: original,
    srcSet: widths.map((width) => ({ src: `${original}?w=${width}`, width })),
    sizes,
  };
};
